def clean_name(value: object) -> object:
    if pd.isna(value):
        return value
    return re.sub(r"_+", "_", re.sub(r"[^A-Za-z0-9]+", "_", str(value).strip())).strip("_")


def embedded_bytes(name: str) -> bytes:
    try:
        payload = (
            EMBEDDED_ASSETS["activity_1"] + EMBEDDED_ASSETS["activity_2"]
            if name == "activity" else EMBEDDED_ASSETS[name]
        )
        return gzip.decompress(base64.b64decode(payload))
    except KeyError as exc:
        raise ValueError(f"Embedded asset is missing: {name}") from exc


def download_file(url: str, path: Path, refresh: bool = False) -> Path:
    if path.exists() and not refresh:
        print(f"Using cached source: {path}")
        return path
    path.parent.mkdir(parents=True, exist_ok=True)
    print(f"Downloading {url}\n  -> {path}")
    request = urllib.request.Request(
        url, headers={"User-Agent": "h2res-standalone-transport/1.0"}
    )
    with urllib.request.urlopen(request, timeout=300) as response, path.open("wb") as target:
        shutil.copyfileobj(response, target, length=1024 * 1024)
    return path


def materialize_embedded_sources(data_dir: Path, refresh: bool = False) -> tuple[Path, Path]:
    helper = data_dir / "helpers" / "allocate_transport_to_nuts3_no_pyrosm.py"
    national_dir = data_dir / "national_transport"
    curves_dir = data_dir / "curves"
    if refresh or not helper.exists():
        helper.parent.mkdir(parents=True, exist_ok=True)
        helper.write_bytes(embedded_bytes("allocator"))
    national = json.loads(embedded_bytes("national").decode("utf-8"))
    for country, files in national.items():
        for name, content in files.items():
            path = national_dir / country / name
            if refresh or not path.exists():
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8", newline="")
    for key, name in zip(("activity", "plugin", "v2g"), CURVE_FILES):
        path = curves_dir / name
        if refresh or not path.exists():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(embedded_bytes(key))
    return helper, national_dir


def download_country_pbfs(
    countries: list[str], data_dir: Path, refresh: bool = False
) -> Path:
    pbf_dir = data_dir / "osm"
    index_path = download_file(
        GEOFABRIK_INDEX_URL, data_dir / "geofabrik-index.json", refresh
    )
    features = json.loads(index_path.read_text(encoding="utf-8"))["features"]
    aliases = {"EL": "GR"}
    for country in countries:
        iso = aliases.get(country, country)
        candidates = [
            feature for feature in features
            if iso in (feature.get("properties", {}).get("iso3166-1:alpha2") or [])
            and feature.get("properties", {}).get("urls", {}).get("pbf")
        ]
        if not candidates:
            print(f"WARNING: no Geofabrik PBF found for {country}; OSM weights will fall back.")
            continue
        feature = min(candidates, key=lambda item: len(item["properties"]["id"]))
        download_file(
            feature["properties"]["urls"]["pbf"],
            pbf_dir / f"{country}.osm.pbf",
            refresh,
        )
    return pbf_dir


def automatic_zone_map(nuts3_path: Path, countries: list[str], out_path: Path) -> Path:
    import geopandas as gpd
    nuts = gpd.read_file(nuts3_path, ignore_geometry=True)
    country_col = "CNTR_CODE" if "CNTR_CODE" in nuts else None
    if country_col is None:
        nuts["CNTR_CODE"] = nuts["NUTS_ID"].astype(str).str[:2]
        country_col = "CNTR_CODE"
    selected = nuts[nuts[country_col].astype(str).str.upper().isin(countries)].copy()
    zone_map = pd.DataFrame({
        "country": selected[country_col].astype(str).str.upper(),
        "nuts3": selected["NUTS_ID"].astype(str),
        "zone": selected["NUTS_ID"].astype(str),
    }).drop_duplicates()
    if zone_map.empty:
        raise ValueError(f"No requested countries found in {nuts3_path}")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    zone_map.to_csv(out_path, index=False)
    return out_path


def prepare_standalone_sources(args: argparse.Namespace) -> None:
    args.data_dir.mkdir(parents=True, exist_ok=True)
    helper, embedded_national = materialize_embedded_sources(
        args.data_dir, args.refresh_sources
    )
    global ALLOCATOR
    ALLOCATOR = helper
    args.nuts3 = args.nuts3 or download_file(
        NUTS_URL, args.data_dir / "NUTS_RG_01M_2021_4326_LEVL_3.geojson",
        args.refresh_sources,
    )
    args.oil_raster = args.oil_raster or download_file(
        f"{RASTER_BASE_URL}/oil_tra_demand_2019.tif",
        args.data_dir / "oil_tra_demand_2019.tif", args.refresh_sources,
    )
    args.el_raster = args.el_raster or download_file(
        f"{RASTER_BASE_URL}/electricity_tra_demand_2019.tif",
        args.data_dir / "electricity_tra_demand_2019.tif", args.refresh_sources,
    )
    args.national_dir = args.national_dir or embedded_national
    args.curves_dir = args.curves_dir or args.data_dir / "curves"
    args.pbf_dir = args.pbf_dir or download_country_pbfs(
        args.countries, args.data_dir, args.refresh_sources
    )
    if args.zone_map is None:
        args.zone_map = automatic_zone_map(
            args.nuts3, args.countries, args.data_dir / "automatic_zone_map.csv"
        )


def base_name(unit: str) -> str:
    for prefix in ("ICE_", "EV_", "FCEV_", "HYBRID_", "EL_"):
        if str(unit).startswith(prefix):
            return str(unit)[len(prefix):]
    return str(unit)


def first_nonnull(values: pd.Series) -> object:
    return next((value for value in values if pd.notna(value)), np.nan)


def defaults(unit: str, tech_type: str) -> dict[str, float]:
    stor, charge = STORAGE_CHARGE.get(
        unit, (0, 0 if tech_type == "EL" else 12000 if tech_type == "FCEV" else 10000)
    )
    return {
        "CO2": {"ICE": .26, "HYBRID": .2}.get(tech_type, 0.0),
        "average_stor": float(stor), "average_ch_rate": float(charge),
        "decom_start_existing_cap": 10, "life_time": 20,
        "decom_start_new": 15, "final_life_cap": .5,
    }


def ensure_row(
    frame: pd.DataFrame, zone: str, system: str, sector: str,
    unit: str, tech_type: str, total_load: float,
) -> pd.DataFrame:
    mask = (
        frame["zone"].eq(zone) & frame["System"].eq(system)
        & frame["sector"].eq(sector) & frame["unit_name"].eq(unit)
        & frame["type"].eq(tech_type)
    )
    if mask.any():
        return frame
    row = {
        "zone": zone, "System": system, "sector": sector, "unit_name": unit,
        "type": tech_type, "total_load": total_load,
        "efficiency_primary": np.nan, "number": 0.0,
    }
    return pd.concat([frame, pd.DataFrame([row])], ignore_index=True)


def infer_efficiencies(frame: pd.DataFrame) -> pd.DataFrame:
    out = frame.copy()
    out["_base"] = out["unit_name"].map(base_name)
    ratios = {
        "car": {"BAT": 4.2, "FCEV": 2.0, "HYBRID": 1.66},
        "BUS": {"BAT": 2.8, "FCEV": 2.0, "HYBRID": 1.5},
        "truck": {"BAT": .47, "FCEV": 2.0, "HYBRID": 1.5},
        "AVIO_SHORT": {"BAT": 3.0, "FCEV": 2.0},
        "AVIO_LONG": {"FCEV": 2.0},
        "MARINE_SHORT": {"BAT": 3.0},
    }
    missing = out["efficiency_primary"].isna()
    for idx, row in out[missing].iterrows():
        peers = out[
            out["System"].eq(row["System"]) & out["zone"].eq(row["zone"])
            & out["sector"].eq(row["sector"]) & out["_base"].eq(row["_base"])
            & out["type"].eq("ICE")
        ]
        if not peers.empty and pd.notna(peers.iloc[0]["efficiency_primary"]):
            ratio = ratios.get(row["_base"], {}).get(row["type"])
            if ratio is not None:
                out.at[idx, "efficiency_primary"] = (
                    float(peers.iloc[0]["efficiency_primary"]) * ratio
                )
    return out.drop(columns="_base")


def load_zone_map(path: Path) -> pd.DataFrame:
    zone_map = pd.read_csv(path)
    aliases = {
        "country": "country", "System": "country", "system": "country",
        "nuts3": "nuts3", "zone_old": "nuts3", "NUTS_ID": "nuts3",
        "zone": "zone", "zone_new": "zone",
    }
    zone_map = zone_map.rename(columns={c: aliases[c] for c in zone_map if c in aliases})
    required = {"country", "nuts3", "zone"}
    if not required.issubset(zone_map):
        raise ValueError(f"Zone map must contain {sorted(required)}; got {list(zone_map)}")
    return zone_map[list(required)].drop_duplicates()


def aggregate_country(country_dir: Path, zone_map_path: Path) -> pd.DataFrame:
    paths = [
        country_dir / "transp1_shape_freight_NUTS3.csv",
        country_dir / "transp1_shape_passenger_NUTS3.csv",
    ]
    missing = [str(path) for path in paths if not path.exists()]
    if missing:
        raise FileNotFoundError("Missing allocated transport tables: " + ", ".join(missing))
    data = pd.concat([pd.read_csv(path) for path in paths], ignore_index=True)
    for col in ("country", "nuts3", "sector", "unit_name", "type"):
        data[col] = data[col].map(clean_name)
    data = transport_identifiers(data)
    electric_rail = data["type"].eq("EL") & data["unit_name"].isin(
        ["EV_RAIL", "EV_RAIL_CARGO"]
    )
    data.loc[electric_rail, "unit_name"] = data.loc[
        electric_rail, "unit_name"
    ].str.replace("EV_", "EL_", regex=False)
    required = {
        "country", "nuts3", "sector", "unit_name", "type",
        "total_load", "number", "efficiency_primary",
    }
    if not required.issubset(data):
        raise ValueError(f"Allocated inputs missing columns: {sorted(required - set(data))}")
    zone_map = load_zone_map(zone_map_path)
    data = data.merge(zone_map, on=["country", "nuts3"], how="left")
    unmapped = data.loc[data["zone"].isna(), ["country", "nuts3"]].drop_duplicates()
    if not unmapped.empty:
        raise ValueError("Unmapped NUTS3 codes:\n" + unmapped.to_string(index=False))
    for col in ("total_load", "number", "efficiency_primary"):
        data[col] = pd.to_numeric(data[col], errors="coerce")

    sector_load = (
        data.drop_duplicates(["country", "zone", "nuts3", "sector"])
        .groupby(["zone", "country", "sector"], as_index=False)["total_load"].sum()
        .rename(columns={"country": "System"})
    )
    tech = (
        data.groupby(["zone", "country", "sector", "unit_name", "type"], as_index=False)
        .agg(number=("number", "sum"), efficiency_primary=("efficiency_primary", first_nonnull))
        .rename(columns={"country": "System"})
    )
    out = tech.merge(sector_load, on=["zone", "System", "sector"], how="left")
    bat = out["type"].eq("BAT") & out["unit_name"].str.startswith("BAT_")
    out.loc[bat, "unit_name"] = out.loc[bat, "unit_name"].str.replace(
        "BAT_", "EV_", regex=False
    )

    hybrid_bases = {"car", "BUS", "truck"}
    ev_bases = hybrid_bases | {"AVIO_SHORT", "MARINE_SHORT"}
    fcev_bases = hybrid_bases | {"AVIO_SHORT", "AVIO_LONG"}
    for (zone, system, sector), group in list(out.groupby(["zone", "System", "sector"])):
        load = float(group.iloc[0]["total_load"])
        for _, row in group[group["type"].eq("ICE")].iterrows():
            base = base_name(row["unit_name"])
            if base in ev_bases:
                out = ensure_row(out, zone, system, sector, f"EV_{base}", "BAT", load)
            if base in fcev_bases:
                out = ensure_row(out, zone, system, sector, f"FCEV_{base}", "FCEV", load)
            if base in hybrid_bases:
                out = ensure_row(out, zone, system, sector, f"HYBRID_{base}", "HYBRID", load)
            if base in {"RAIL", "RAIL_CARGO"}:
                out = ensure_row(out, zone, system, sector, f"EL_{base}", "EL", load)

    extra = out.apply(
        lambda row: defaults(row["unit_name"], row["type"]), axis=1,
        result_type="expand",
    )
    out = pd.concat([out.reset_index(drop=True), extra.reset_index(drop=True)], axis=1)
    out["number"] = pd.to_numeric(out["number"], errors="coerce").fillna(0.0)
    out = infer_efficiencies(out)
    return out[FINAL_COLUMNS].sort_values(
        ["System", "zone", "sector", "unit_name", "type"]
    ).reset_index(drop=True)


def model_ready(frame: pd.DataFrame) -> pd.DataFrame:
    out = transport_identifiers(frame)
    out.insert(9, "max_share", out["unit_name"].map(MAX_SHARE).fillna(1.0))
    out["EV_grid_eff"] = .9
    out["include_in_the_model"] = "Y"
    for year in range(2020, 2051):
        out[year] = 0 if year <= 2025 else 200_000_000 if year == 2026 else 500_000_000
    return out[TRANSPORT_ALL_COLUMNS]


def transport_ice_prim(transport_all: pd.DataFrame) -> pd.DataFrame:
    """Create primary-fuel definitions, including the current e-petrol route."""
    transport_all = transport_identifiers(transport_all)
    combustion = transport_all.loc[transport_all.type.isin(["ICE", "HYBRID"]), "unit_name"]
    missing = set(combustion) - set(ICE_PRIMARY_FUELS)
    if missing:
        raise ValueError(f"No primary-fuel compatibility mapping for transport units: {sorted(missing)}")
    rows: list[dict[str, object]] = []
    zones = transport_all[["System", "zone"]].drop_duplicates()
    for system, zone in zones.itertuples(index=False):
        for sector_prim, fuels in ICE_PRIMARY_FUELS.items():
            for fuel, share, maximum, co2, fossil in fuels:
                rows.append({
                    "sector_prim": sector_prim, "fuel_prim": fuel,
                    "share2020prim": share, "max_share": maximum,
                    "CO2prim": co2, "fossil": fossil, "zone": zone,
                    "system": system, "use": "Y", ICE_PRIM_NOTE: None,
                })
    result = pd.DataFrame(rows, columns=ICE_PRIM_COLUMNS)
    expected = len(zones) * sum(len(fuels) for fuels in ICE_PRIMARY_FUELS.values())
    if len(result) != expected:
        raise ValueError(f"transport_ICE_prim expected {expected} rows, got {len(result)}")
    return result


def write_distribution_curves(curves_dir: Path, output_dir: Path) -> None:
    """Write typical curves on the common 8760-hour model calendar."""
    for name in CURVE_FILES:
        source = curves_dir / name
        if not source.exists():
            raise FileNotFoundError(f"Typical transport curve not found: {source}")
        curve = pd.read_csv(source)
        if "timestamp" not in curve or len(curve) not in (8760, 8784):
            raise ValueError(f"Invalid transport curve {source}: {curve.shape}")
        if len(curve) == 8784:
            timestamp = pd.to_datetime(curve["timestamp"], errors="raise")
            curve = curve.loc[~((timestamp.dt.month == 2) & (timestamp.dt.day == 29))].copy()
            if name == "hourly_activity_share.csv":
                value_cols = [col for col in curve.columns if col != "timestamp"]
                totals = curve[value_cols].sum()
                if (totals <= 0).any():
                    raise ValueError(f"Cannot normalize zero-valued activity curve: {source}")
                curve[value_cols] = curve[value_cols].div(totals, axis=1)
        if len(curve) != 8760:
            raise ValueError(f"Transport curve did not normalize to 8760 hours: {source}")
        curve.to_csv(output_dir / name, index=False)
    print(f"Wrote activity, plug-in and V2G curves to {output_dir}")


def write_model_curves(transport_all: pd.DataFrame, output_dir: Path) -> None:
    """Write the reader's sector demand shares and per-unit plug-in fractions."""
    transport_all = transport_identifiers(transport_all)
    activity = pd.read_csv(output_dir / "hourly_activity_share.csv").drop(columns="timestamp")
    plugin = pd.read_csv(output_dir / "hourly_plug_in_availability.csv").drop(columns="timestamp")
    activity.columns = [clean_name(c) for c in activity]
    plugin.columns = [clean_name(c) for c in plugin]
    demand_frames, availability_frames = [], []
    for (system, zone), group in transport_all.groupby(["System", "zone"], sort=False):
        demand = pd.DataFrame({"period": np.arange(1, 8761), "zone": zone, "System": system})
        available = demand.copy()
        for sector in group.sector.unique():
            if sector not in activity or sector not in plugin:
                raise ValueError(f"No typical transport curve for sector {sector}")
            values = pd.to_numeric(activity[sector], errors="raise")
            if (values < 0).any() or values.sum() <= 0:
                raise ValueError(f"Invalid activity shares for {sector}")
            demand[sector] = values / values.sum()
        for row in group.itertuples(index=False):
            values = pd.to_numeric(plugin[row.sector], errors="raise")
            if not values.between(0, 1).all():
                raise ValueError(f"Invalid plug-in fractions for {row.sector}")
            available[row.unit_name] = values
        demand_frames.append(demand)
        availability_frames.append(available)
    pd.concat(demand_frames, ignore_index=True).to_csv(output_dir / "transport_demand.csv", index=False)
    pd.concat(availability_frames, ignore_index=True).to_csv(output_dir / "transport_profiles.csv", index=False)


def validate(compact: pd.DataFrame, ready: pd.DataFrame) -> None:
    if compact.empty or ready.empty:
        raise ValueError("Transport output is empty")
    if list(ready.columns) != TRANSPORT_ALL_COLUMNS:
        raise ValueError("transport_all column layout is invalid")
    bad = compact.groupby(["System", "zone", "sector"])["total_load"].nunique()
    if (bad > 1).any():
        raise ValueError("total_load differs between technologies in a sector block")
    print(
        f"Validated {len(ready):,} technology rows, "
        f"{ready['zone'].nunique()} zones and {ready['sector'].nunique()} sectors."
    )


def run_allocator(args: argparse.Namespace) -> None:
    missing = [
        name for name in ("nuts3", "national_dir", "pbf_dir")
        if getattr(args, name) is None
    ]
    if missing:
        raise ValueError(
            "Allocation requires: " + ", ".join(f"--{name.replace('_', '-')}" for name in missing)
        )
    spec = importlib.util.spec_from_file_location("transport_nuts3_allocator", ALLOCATOR)
    if spec is None or spec.loader is None:
        raise ImportError(f"Cannot load allocator: {ALLOCATOR}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    from activity_units import ensure_energy_column
    module.ensure_energy_column = ensure_energy_column
    from osm_infrastructure import weights
    import geopandas as gpd
    geography = gpd.read_file(args.nuts3)
    if "COAST_TYPE" not in geography:
        raise ValueError("Paper-method maritime allocation requires GISCO COAST_TYPE geography")
    coastal = pd.to_numeric(geography.set_index("NUTS_ID").COAST_TYPE, errors="raise").to_dict()
    indicators = {}
    shipping_by_regions = {}
    def infrastructure(nuts, path, metric_crs="EPSG:3035"):
        key = (str(path), tuple(nuts.NUTS_ID), metric_crs)
        if key not in indicators:
            indicators.clear()
            indicators[key] = weights(nuts, path, coastal, metric_crs, include_inland=True)
        return indicators[key]
    module.rail_lengths_by_nuts3 = lambda nuts, path, metric_crs="EPSG:3035": infrastructure(nuts,path,metric_crs)[0]
    def navigation_weights(nuts, path, metric_crs="EPSG:3035"):
        frame = infrastructure(nuts, path, metric_crs)[1]
        shipping_by_regions[tuple(nuts.NUTS_ID)] = frame
        return frame
    module.shipping_weights_by_nuts3 = navigation_weights
    module.aviation_weights_by_nuts3 = lambda nuts, path, metric_crs="EPSG:3035": infrastructure(nuts,path,metric_crs)[2]
    from transport.script.navigation_allocation import allocate_table, METHOD
    original_allocate = module.allocate_table_to_nuts3_complete
    args.paper_navigation = {}
    args.paper_navigation_method = METHOD
    def navigation_safe_allocation(national, nuts_ids, weights, table_kind):
        notes = args.paper_navigation.setdefault(nuts_ids[0][:2], [])
        return allocate_table(original_allocate, national, nuts_ids, weights, table_kind,
                              coastal, shipping_by_regions[tuple(nuts_ids)], notes)
    module.allocate_table_to_nuts3_complete = navigation_safe_allocation
    allocator_args = [
        str(ALLOCATOR), "--countries", ",".join(args.countries),
        "--nuts3", str(args.nuts3), "--pbf-dir", str(args.pbf_dir),
        "--national-dir", str(args.national_dir), "--out", str(args.out_root),
        "--metric-crs", args.metric_crs,
    ]
    if args.oil_raster:
        allocator_args += ["--oil-raster", str(args.oil_raster)]
    if args.el_raster:
        allocator_args += ["--el-raster", str(args.el_raster)]
    old_argv = sys.argv
    args.paper_allocator = str(ALLOCATOR)
    try:
        sys.argv = allocator_args
        module.main()
    finally:
        sys.argv = old_argv
    for ids, frame in shipping_by_regions.items():
        debug_path = args.out_root / ids[0][:2] / "debug_weights_NUTS3.csv"
        debug = pd.read_csv(debug_path)
        for column in ("ship_inland_freight", "ship_inland_passenger"):
            debug[column] = debug.NUTS_ID.map(dict(zip(ids, frame[column])))
        debug.to_csv(debug_path, index=False)
    from sector_method_provenance import transport_allocation, validate_transport_allocation
    transport_allocation(args)
    validate_transport_allocation(args)


def parse_countries(raw: str) -> list[str]:
    return [item.strip().upper() for item in raw.split(",") if item.strip()]


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Allocate, aggregate and format all H2RES transport inputs."
    )
    parser.add_argument("--countries", type=parse_countries, default=parse_countries("HR"))
    parser.add_argument("--nuts3", type=Path)
    parser.add_argument("--national-dir", type=Path)
    parser.add_argument("--pbf-dir", type=Path)
    parser.add_argument("--oil-raster", type=Path)
    parser.add_argument("--el-raster", type=Path)
    parser.add_argument("--zone-map", type=Path)
    parser.add_argument("--out-root", type=Path, default=SCRIPT_DIR / "outputs_transport")
    parser.add_argument("--data-dir", type=Path, default=DEFAULT_DATA_DIR)
    parser.add_argument("--curves-dir", type=Path)
    parser.add_argument("--refresh-sources", action="store_true")
    parser.add_argument(
        "--efuels", action=argparse.BooleanOptionalAction, default=False,
        help="Also generate transport_ICE_prim. Without this flag only transport_all is written.",
    )
    parser.add_argument("--metric-crs", default="EPSG:3035")
    parser.add_argument(
        "--skip-allocation", action="store_true",
        help="Aggregate existing *_NUTS3.csv files without repeating geospatial allocation.",
    )
    return parser


def main(argv: Iterable[str] | None = None) -> int:
    args = build_parser().parse_args(list(argv) if argv is not None else None)
    try:
        if not args.skip_allocation:
            prepare_standalone_sources(args)
            run_allocator(args)
        elif args.curves_dir is None:
            _, _ = materialize_embedded_sources(args.data_dir, args.refresh_sources)
            args.curves_dir = args.data_dir / "curves"
        if args.zone_map is None:
            if args.nuts3 is None:
                raise ValueError("--zone-map or --nuts3 is required with --skip-allocation")
            args.zone_map = automatic_zone_map(
                args.nuts3, args.countries, args.data_dir / "automatic_zone_map.csv"
            )
        combined: list[pd.DataFrame] = []
        for country in args.countries:
            country_dir = args.out_root / country
            compact = aggregate_country(country_dir, args.zone_map)
            ready = model_ready(compact)
            primary = transport_ice_prim(ready) if args.efuels else None
            validate(compact, ready)
            compact.to_csv(country_dir / "transp1_shape_AGG_new.csv", index=False)
            ready.to_csv(country_dir / "transport_all.csv", index=False)
            if primary is not None:
                primary.to_csv(country_dir / "transport_ICE_prim.csv", index=False)
            else:
                (country_dir / "transport_ICE_prim.csv").unlink(missing_ok=True)
            write_distribution_curves(args.curves_dir, country_dir)
            write_model_curves(ready, country_dir)
            with pd.ExcelWriter(
                country_dir / "transport_inputs.xlsx", engine="openpyxl"
            ) as writer:
                ready.to_excel(writer, sheet_name="transport_all", index=False)
                if primary is not None:
                    primary.to_excel(writer, sheet_name="transport_ICE_prim", index=False)
            combined.append(ready)
            print(f"Wrote model-ready transport inputs: {country_dir / 'transport_inputs.xlsx'}")
        if combined:
            combined_dir = args.out_root / "combined"
            combined_dir.mkdir(parents=True, exist_ok=True)
            all_ready = pd.concat(combined, ignore_index=True)
            all_ready.to_csv(combined_dir / "transport_all.csv", index=False)
            all_primary = transport_ice_prim(all_ready) if args.efuels else None
            if all_primary is not None:
                all_primary.to_csv(combined_dir / "transport_ICE_prim.csv", index=False)
            else:
                (combined_dir / "transport_ICE_prim.csv").unlink(missing_ok=True)
            write_distribution_curves(args.curves_dir, combined_dir)
            write_model_curves(all_ready, combined_dir)
            with pd.ExcelWriter(
                combined_dir / "transport_inputs.xlsx", engine="openpyxl"
            ) as writer:
                all_ready.to_excel(writer, sheet_name="transport_all", index=False)
                if all_primary is not None:
                    all_primary.to_excel(
                        writer, sheet_name="transport_ICE_prim", index=False
                    )
        from sector_method_provenance import write_transport
        write_transport(args)
        return 0
    except (FileNotFoundError, ImportError, ValueError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
